{"content": "from __future__ import annotations
from fastapi import FastAPI
from pydantic import BaseModel
import pytest

app = FastAPI()

class Item(BaseModel):
    name: str
    price: float

@app.get("/items/{item_id}")
async def read_item(item_id: int, item: Item):
    return {"item_id": item_id, "item": item}

def test_annotations():
    import inspect
    sig = inspect.signature(read_item)
    print(f"Signature: {sig}")
    for name, param in sig.parameters.items():
        print(f"Parameter {name}: {param.annotation}")
        # In Python 3.10 with from __future__ import annotations, 
        # param.annotation should be a string if not evaluated.
        # FastAPI should be able to handle this.

if __name__ == "__main__":
    test_annotations()
", "filepath": "/_check.py"}

